IF OBJECT_ID(N'gb_talk_session', N'U') IS NOT NULL AND COL_LENGTH(N'gb_talk_session', N'target_id') IS NULL ALTER TABLE [gb_talk_session] ADD [target_id] nvarchar(20) NOT NULL CONSTRAINT [df_gb_talk_target_id] DEFAULT N'';
IF OBJECT_ID(N'gb_talk_session', N'U') IS NOT NULL AND COL_LENGTH(N'gb_talk_session', N'broadcast_sn') IS NULL ALTER TABLE [gb_talk_session] ADD [broadcast_sn] bigint NOT NULL CONSTRAINT [df_gb_talk_broadcast_sn] DEFAULT 0;
IF OBJECT_ID(N'gb_talk_session', N'U') IS NOT NULL AND COL_LENGTH(N'gb_talk_session', N'broadcast_reply_status') IS NULL ALTER TABLE [gb_talk_session] ADD [broadcast_reply_status] nvarchar(32) NOT NULL CONSTRAINT [df_gb_talk_broadcast_reply] DEFAULT N'';
IF OBJECT_ID(N'gb_talk_session', N'U') IS NOT NULL AND COL_LENGTH(N'gb_talk_session', N'signal_phase') IS NULL ALTER TABLE [gb_talk_session] ADD [signal_phase] nvarchar(40) NOT NULL CONSTRAINT [df_gb_talk_signal_phase] DEFAULT N'';
IF OBJECT_ID(N'gb_talk_session', N'U') IS NOT NULL AND COL_LENGTH(N'gb_talk_session', N'remote_media_ip') IS NULL ALTER TABLE [gb_talk_session] ADD [remote_media_ip] nvarchar(64) NOT NULL CONSTRAINT [df_gb_talk_remote_ip] DEFAULT N'';
IF OBJECT_ID(N'gb_talk_session', N'U') IS NOT NULL AND COL_LENGTH(N'gb_talk_session', N'remote_media_port') IS NULL ALTER TABLE [gb_talk_session] ADD [remote_media_port] int NOT NULL CONSTRAINT [df_gb_talk_remote_port] DEFAULT 0;
IF OBJECT_ID(N'gb_talk_session', N'U') IS NOT NULL AND COL_LENGTH(N'gb_talk_session', N'media_transport') IS NULL ALTER TABLE [gb_talk_session] ADD [media_transport] nvarchar(16) NOT NULL CONSTRAINT [df_gb_talk_media_transport] DEFAULT N'';
IF OBJECT_ID(N'gb_talk_session', N'U') IS NOT NULL AND COL_LENGTH(N'gb_talk_session', N'sender_mode') IS NULL ALTER TABLE [gb_talk_session] ADD [sender_mode] nvarchar(24) NOT NULL CONSTRAINT [df_gb_talk_sender_mode] DEFAULT N'';
IF OBJECT_ID(N'gb_talk_session', N'U') IS NOT NULL AND NOT EXISTS (SELECT 1 FROM sys.indexes WHERE name = N'idx_talk_session_broadcast_match' AND object_id = OBJECT_ID(N'gb_talk_session')) CREATE INDEX [idx_talk_session_broadcast_match] ON [gb_talk_session]([device_id], [target_id], [state]);
IF OBJECT_ID(N'gb_talk_session', N'U') IS NOT NULL AND NOT EXISTS (SELECT 1 FROM sys.indexes WHERE name = N'idx_talk_session_broadcast_sn' AND object_id = OBJECT_ID(N'gb_talk_session')) CREATE INDEX [idx_talk_session_broadcast_sn] ON [gb_talk_session]([broadcast_sn]);
